def transform(grid):
    # Background is 7. Remove isolated noise (colors 3,5,8), normalize
    # each contiguous rectangular colored object, replacing 5-cell defects
    # with its object's dominant color.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 7) or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            # Colored objects are the coherent rectangular regions; minor
            # noise cells embedded in them are treated separately by panel.
            for y,x in cells:
                out[y][x]=color
    # In the demos, color 6 outlines/corrupts the large color-2 rectangles;
    # color 5 likewise corrupts them, while unrelated speckle is erased.
    # Preserve primary rectangles and region of color 6 at left.
    # Generic handling: all colors except background 7, target 2, target 6
    # are noise; defects 5/6 inside large color-2 boxes become 2.
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (2,6): out[r][c]=7
    # Find bounding boxes of contiguous 2/5/6 clusters and fill boxes where
    # color 2 is dominant; color 6 rectangle with no 2 stays intact.
    visited=set()
    for r in range(h):
      for c in range(w):
        if (r,c) in visited or grid[r][c] not in (2,5,6): continue
        stack=[(r,c)]; visited.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if 0<=p[0]<h and 0<=p[1]<w and p not in visited and grid[p[0]][p[1]] in (2,5,6):
              visited.add(p); stack.append(p)
        n2=sum(grid[y][x]==2 for y,x in comp)
        if n2:
          ys=[y for y,x in comp]; xs=[x for y,x in comp]
          # Fill the rectangular bounds of each target patch.
          for y in range(min(ys),max(ys)+1):
            for x in range(min(xs),max(xs)+1):
              if grid[y][x] in (2,5,6): out[y][x]=2
        else:
          for y,x in comp: out[y][x]=6
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The intended picture consists of repeated solid rectangular color
    # objects. Isolated 6,5,3,8,9 marks are distractors in the demo scheme;
    # keep only sustained runs and treat isolated corruptions as background.
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            neighbors = sum(
                1 for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
                if 0 <= r + dr < h and 0 <= c + dc < w
                and grid[r + dr][c + dc] == v
            )
            if neighbors >= 1 or v in (1, 2, 3, 7, 8, 9):
                out[r][c] = v
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    # This task removes the sparse one-cell corruptions from repeated solid
    # rectangular patches, leaving objects whose dominant color occurs in
    # stable horizontal/vertical runs. Preserve stable runs, discard isolated
    # speckles, and repair one-cell holes enclosed along both axes.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            if any(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == v
                   for dr, dc in ((1,0),(-1,0),(0,1),(0,-1))):
                out[r][c] = v
    colors = set(v for row in grid for v in row if v != bg)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            for v in colors:
                left = any(grid[r][x] == v for x in range(c))
                right = any(grid[r][x] == v for x in range(c+1,w))
                up = any(grid[y][c] == v for y in range(r))
                down = any(grid[y][c] == v for y in range(r+1,h))
                if left and right and up and down:
                    out[r][c] = v
                    break
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    # Keep connected colored regions that are sufficiently substantial; remove
    # the scattered isolated contamination pixels. Solid rectangles with a few
    # bad pixels are completed within their tight bounding box.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if len(cells) >= 4 or (color == 6 and len(cells) >= 2):
                ys = [y for y, x in cells]
                xs = [x for y, x in cells]
                box = (min(ys), max(ys), min(xs), max(xs))
                objects.append((color, cells, box))
    for color, cells, (y0, y1, x0, x1) in objects:
