def transform(grid):
    # Each object is a rectangle-like template of color 6, separated by
    # color-1 framing rows/columns. Remove sparse distracting marks from the
    # frame and rectangles, preserving the main color-6 regions.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
