def transform(grid):
    # Retain the largest solid, rectangular component of non-background pixels
    # and complete it; use exact input shape throughout.
    h=len(grid); w=max(map(len,grid))
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*len(row) for row in grid]
    seen=set(); comps=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==bg or (r,c) in seen: continue
            q=[(r,c)];seen.add((r,c));cells=[]
            while q:
                y,x=q.pop();cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<len(grid[yy]) and (yy,xx) not in seen and grid[yy][xx]==v:
                        seen.add((yy,xx));q.append((yy,xx))
            comps.append((len(cells),v,cells))
    if not comps: return out
    # Main object is the densest sufficiently large rectangular component(s).
    for n,v,cells in comps:
        y0=min(y for y,x in cells);y1=max(y for y,x in cells)
        x0=min(x for y,x in cells);x1=max(x for y,x in cells)
        area=(y1-y0+1)*(x1-x0+1)
        if n>=3 and n/area>=0.70:
            for y in range(y0,y1+1):
                for x in range(x0,x1+1): out[y][x]=v
    return out

