    # toward its opposing edge, recoloring the ray with its original color;
    # replace the pixel itself by 4.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # Boundary bars are non-background colors on an edge. Isolated marker
    # colors are the non-background colors not forming a long edge run.
    edge_runs = {}
    for v in counts:
        if v == bg:
            continue
        edge_runs[v] = max(
            max(sum(grid[r][c] == v for c in range(w)) for r in range(h)),
            max(sum(grid[r][c] == v for r in range(h)) for c in range(w)),
        )
    marker = min(edge_runs, key=lambda v: edge_runs[v])
    bars = {v for v, run in edge_runs.items() if run >= 2 and v != marker}
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for r,c in markers:
        out[r][c] = 4
