        if c < w-1: candidates.append((w-1-c, 'right', grid[r][w-1]))
        if r > 0: candidates.append((r, 'up', grid[0][c]))
        if r < h-1: candidates.append((h-1-r, 'down', grid[h-1][c]))
        candidates.sort()
