    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find the separator column (a constant-color column) and horizontal rails.
    sep=next(c for c in range(w) if len({g[r][c] for r in range(h)})==1)
    rails=[r for r in range(h) if len(set(g[r]))==1]
    # First phenomenon: copy color-marked cells in left block across the
    # separator, reflecting columns, only where the opposite side is blank.
    leftw=sep; rightw=w-sep-1
    if leftw==rightw:
        for r in range(h):
            for c in range(leftw):
                if g[r][c] not in (1, g[r][0]) and g[r][w-1-c]==1:
                    g[r][w-1-c]=g[r][c]
    # Repeated horizontal blocks: copy the sparse pattern in the first block
    # to later blocks, preserving colored marks over the uniform background.
    if rails:
        top_end=rails[0]
        if top_end>0:
            base=[row[:] for row in g[:top_end]]
            for rail_i,rail in enumerate(rails):
                next_rail=rails[rail_i+1] if rail_i+1<len(rails) else h
                lo=rail+1; hi=next_rail
                if hi-lo==top_end:
                    for k,r in enumerate(range(lo,hi)):
                        bg=g[r][0]
                        for c in range(w):
                            if g[r][c]==bg and base[k][c]!=base[k][0]:
                                g[r][c]=base[k][c]
    return g

